// packages/core/src/slack-answer.ts
// The Slack documentation bot's answer pattern, shared by its two hosts:
//   • the desktop — apps/api/src/slack/slack.service.ts, Slack events over Socket Mode, the
//     answer generated by the member's agent runtime;
//   • the cloud — supabase/functions/slack-events, Slack events over HTTP, the answer
//     generated with the AI key the workspace owner stored.
// Both hosts call answerSlackAsk and differ only in how they search and how they generate,
// so a question gets the same placeholder, prompt, formatting, splitting and fixed replies
// whichever host answers it.
//
// NO IMPORTS, on purpose: the Edge Function imports this file by relative path from Deno,
// which resolves neither extensionless specifiers nor workspace packages. Keep it
// self-contained — types it needs are declared here structurally.

// ── Slack message shapes ─────────────────────────────────────────────────────────

// A message as conversations.replies (and the Events API) carry it. Typed loosely on
// purpose — classifyMessage is the tolerant boundary that decides what a message means.
export type SlackRawMessage = {
  user?: string;
  bot_id?: string;
  text?: string;
  ts: string;
  thread_ts?: string;
  subtype?: string;
};

export type SlackAsk = {
  kind: "question" | "followup";
  channel: string;
  // The thread the answer goes into: the question's own ts for a top-level message, the
  // root's ts for a follow-up.
  threadTs: string;
  ts: string;
  text: string;
};

// Plain messages, replies also sent to the channel, and messages with an attachment are
// things a person typed. Every other subtype is an edit (`message_changed`), a deletion,
// a join notice or a bot post — none of them is a question.
const HUMAN_SUBTYPES = new Set<string | undefined>([undefined, "thread_broadcast", "file_share"]);

// Slack renders a mention as `<@U123>` and occasionally as `<@U123|name>`.
function mentionPattern(botUserId: string): RegExp {
  return new RegExp(`<@${botUserId}(?:\\|[^>]*)?>`, "g");
}

function stripMention(text: string, botUserId: string): string {
  return text.replace(mentionPattern(botUserId), " ").replace(/[ \t]{2,}/g, " ").trim();
}

// What one Events API message means for the bot. Every top-level message in the bound
// channel is a question; inside a thread only a message that @-mentions the bot is
// addressed to it — the rest is people talking to each other.
export function classifyMessage(event: unknown, botUserId: string): SlackAsk | null {
  if (!event || typeof event !== "object") return null;
  const e = event as Partial<SlackRawMessage> & { type?: string; channel?: string };
  if (e.type !== "message" || !HUMAN_SUBTYPES.has(e.subtype)) return null;
  // The bot's own replies arrive as events too; answering them would be a loop.
  if (e.bot_id || !e.user || e.user === botUserId) return null;
  if (typeof e.channel !== "string" || typeof e.ts !== "string") return null;

  const raw = e.text ?? "";
  const topLevel = !e.thread_ts || e.thread_ts === e.ts;
  if (!topLevel && !mentionPattern(botUserId).test(raw)) return null;

  const text = stripMention(raw, botUserId);
  if (!text) return null;
  return {
    kind: topLevel ? "question" : "followup",
    channel: e.channel,
    threadTs: topLevel ? e.ts : e.thread_ts!,
    ts: e.ts,
    text,
  };
}

export type TranscriptLine = { who: string; text: string };

// The thread as the model reads it, in order. People stay `<@U…>` — the bot holds no
// users:read scope to resolve names, and the raw mention is still a stable «who said what».
// `excludeTs` drops the placeholder the bot just posted for the very answer being written.
export function threadTranscript(messages: SlackRawMessage[], botUserId: string, excludeTs?: string): TranscriptLine[] {
  const out: TranscriptLine[] = [];
  for (const m of messages) {
    if (m.ts === excludeTs) continue;
    const text = stripMention(m.text ?? "", botUserId);
    if (!text) continue;
    const isBot = !!m.bot_id || m.user === botUserId;
    out.push({ who: isBot ? "Kermanych" : `<@${m.user ?? "unknown"}>`, text });
  }
  return out;
}

// ── Slack mrkdwn ─────────────────────────────────────────────────────────────────

// The inline conversions, applied only outside backtick code spans: a span is literal in
// both dialects, and `**` inside one is code, not emphasis. Links go first, so a bold link
// text keeps its link, then both bold spellings onto Slack's single asterisk.
function outsideCodeSpans(line: string): string {
  return line
    .split(/(`[^`]*`)/)
    .map((part, i) =>
      i % 2 === 1
        ? part
        : part
            .replace(/\[([^\]]+)\]\((\S+?)\)/g, "<$2|$1>")
            .replace(/\*\*(.+?)\*\*/g, "*$1*")
            .replace(/__(.+?)__/g, "*$1*"),
    )
    .join("");
}

// Models write CommonMark; Slack renders its own mrkdwn, where `**x**` shows asterisks,
// `#` is a literal hash and `[t](url)` is not a link. Only those three are converted —
// lists, quotes and code read the same in both — and fenced blocks pass through untouched.
export function toSlackMrkdwn(markdown: string): string {
  let inFence = false;
  return markdown
    .split("\n")
    .map((line) => {
      if (/^\s*```/.test(line)) {
        inFence = !inFence;
        return line;
      }
      if (inFence) return line;
      const heading = /^\s{0,3}#{1,6}\s+(.*?)\s*#*\s*$/.exec(line);
      if (heading) {
        // Slack has no headings; a bold line is the convention. Emphasis already inside the
        // heading is dropped so it does not toggle the bold off halfway.
        const inner = outsideCodeSpans(heading[1]!.replace(/\*\*|__/g, ""));
        return inner ? `*${inner}*` : "";
      }
      return outsideCodeSpans(line);
    })
    .join("\n");
}

// What one Slack message may carry. `chat.update` — which turns the placeholder into the
// answer — rejects `text` over 4,000 characters with `msg_too_long`, and `chat.postMessage`
// starts truncating soon after. The margin covers Slack counting differently from
// `String.length` (entities, emoji).
export const SLACK_TEXT_LIMIT = 3_500;

const FENCE = /^\s*```/;

// A long answer as consecutive Slack messages, each within `limit`, so the whole answer
// arrives instead of an error. Breaks fall between paragraphs where they can, then between
// lines, and only a line longer than half a message is cut mid-line. A code block cut in
// two is closed at the end of one message and reopened at the start of the next, so both
// halves still render as code.
export function splitForSlack(text: string, limit = SLACK_TEXT_LIMIT): string[] {
  const chunks: string[] = [];
  let current = "";
  for (const block of paragraphs(text)) {
    if (block.length > limit) {
      // Its pieces are each near a whole message: they go out on their own.
      if (current) chunks.push(current);
      const pieces = splitLines(block, limit);
      chunks.push(...pieces.slice(0, -1));
      current = pieces[pieces.length - 1]!;
      continue;
    }
    const joined = current ? `${current}\n\n${block}` : block;
    if (joined.length <= limit) {
      current = joined;
    } else {
      chunks.push(current);
      current = block;
    }
  }
  if (current) chunks.push(current);
  return chunks.length > 0 ? chunks : [text];
}

// Blank-line separated blocks; a blank line inside a code fence belongs to the code.
function paragraphs(text: string): string[] {
  const out: string[] = [];
  let lines: string[] = [];
  let inFence = false;
  for (const line of text.split("\n")) {
    if (FENCE.test(line)) inFence = !inFence;
    if (!inFence && line.trim() === "") {
      if (lines.length > 0) out.push(lines.join("\n"));
      lines = [];
    } else {
      lines.push(line);
    }
  }
  if (lines.length > 0) out.push(lines.join("\n"));
  return out;
}

// One oversized block, packed line by line. The pieces of a cut line continue each other
// without a newline while they share a message. The reopening fence is a bare ``` — Slack
// shows a language tag as the first line of code, and a bare one keeps the reopen short.
function splitLines(block: string, limit: number): string[] {
  const out: string[] = [];
  const close = "\n```";
  let lines: string[] = [];
  let size = 0;
  let inFence = false;
  const add = (piece: string, join: boolean): void => {
    if (join) {
      lines[lines.length - 1] += piece;
      size += piece.length;
    } else {
      size += (lines.length > 0 ? 1 : 0) + piece.length;
      lines.push(piece);
    }
  };
  for (const whole of block.split("\n")) {
    const isFence = FENCE.test(whole);
    const pieces = isFence ? [whole] : cutLine(whole, Math.floor(limit / 2));
    const fenceAfter: boolean = isFence ? !inFence : inFence;
    pieces.forEach((piece, i) => {
      let join = i > 0;
      const glue = join || lines.length === 0 ? 0 : 1;
      if (lines.length > 0 && size + glue + piece.length + (fenceAfter ? close.length : 0) > limit) {
        out.push(inFence ? lines.join("\n") + close : lines.join("\n"));
        lines = [];
        size = 0;
        join = false;
        if (inFence) add("```", false);
      }
      add(piece, join);
    });
    inFence = fenceAfter;
  }
  if (lines.length > 0) out.push(lines.join("\n"));
  return out;
}

// A line no longer than `max` per piece: cut after the last space in the back half, else at
// `max`; never inside a `<url|label>` link or between the halves of a surrogate pair.
function cutLine(line: string, max: number): string[] {
  const out: string[] = [];
  let rest = line;
  while (rest.length > max) {
    let cut = rest.lastIndexOf(" ", max - 1) + 1;
    if (cut < max / 2) cut = max;
    const open = rest.lastIndexOf("<", cut - 1);
    if (open > 0 && open > rest.lastIndexOf(">", cut - 1)) cut = open;
    const code = rest.charCodeAt(cut - 1);
    if (code >= 0xd800 && code <= 0xdbff) cut--;
    out.push(rest.slice(0, cut));
    rest = rest.slice(cut);
  }
  out.push(rest);
  return out;
}

// ── The prompt ───────────────────────────────────────────────────────────────────
// The rules are the management chat's documentation protocol (management-prompt.ts
// docsProtocol) re-stated for Slack: answer only from the fragments, never invent, explain
// in plain words for a non-technical reader — but cite as plain text, because Slack has no
// `kdoc:` links to open a file in Kermanych's preview, and format as Slack mrkdwn.
//
// English, unlike the management prompts: the channel's audience is whoever is in that
// Slack workspace, and the reply language follows the QUESTION, not the operator.

// The exact sentence the bot owes a question the documentation does not cover. Fixed, so a
// reader learns to recognise it as «not built», not as a model being vague.
export const NOT_BUILT_REPLY = "We do not have such feature built yet.";

// A prompt budget for the fragments. Eight matches per project across a few projects is
// already far more than one answer needs; past this the least relevant are dropped (the
// search returns them best-first) rather than letting a large workspace grow the prompt
// without bound.
const MAX_FRAGMENT_CHARS = 40_000;

// One retrieved documentation fragment — structurally ManagementDocFragment, which is what
// the docs-rag search returns.
export type SlackDocFragment = {
  folder: string;
  path: string;
  headingPath: string;
  startLine: number;
  endLine: number;
  content: string;
};

export type SlackPromptDocs = { projectName: string; fragments: SlackDocFragment[] };

export type SlackPromptInput = {
  workspaceName?: string;
  // Earlier messages of the thread, oldest first, WITHOUT the question itself.
  transcript: TranscriptLine[];
  question: string;
  docs: SlackPromptDocs[];
};

function fragmentLines(projectName: string, f: SlackDocFragment): string {
  const head = `- ${projectName} › ${f.folder}/${f.path} › ${f.headingPath || "(no heading)"} (lines ${f.startLine}–${f.endLine})`;
  return [head, ...f.content.split("\n").map((l) => `    ${l}`)].join("\n");
}

function docsBlock(docs: SlackPromptDocs[]): string {
  const blocks: string[] = [];
  let used = 0;
  for (const d of docs)
    for (const f of d.fragments) {
      const block = fragmentLines(d.projectName, f);
      if (used + block.length > MAX_FRAGMENT_CHARS) break;
      used += block.length;
      blocks.push(block);
    }
  return blocks.length ? blocks.join("\n") : "- (no fragment matched the question)";
}

export function buildSlackAnswerPrompt(input: SlackPromptInput): string {
  const where = input.workspaceName ? ` for the Kermanych workspace «${input.workspaceName}»` : "";
  return [
    `You are Kermanych, answering a question in a Slack thread${where}. Your only source of truth is the project documentation fragments below.`,
    "",
    "RULES:",
    "1. Answer ONLY from the documentation fragments. The thread is conversational context (what was already asked and answered), never a source of facts about the product.",
    "2. Never invent features, settings, paths or behaviour, and never fill gaps from general knowledge.",
    `3. If the fragments do not describe what is asked, reply with exactly «${NOT_BUILT_REPLY}» — translated into the question's language if it is not English — and nothing else.`,
    "4. Reply in the language the question is written in.",
    "5. Format as Slack mrkdwn: no # headings, *bold* with single asterisks, `code` in backticks, links as <url|text>. Short paragraphs or bullet lists.",
    "6. Write for a non-technical reader, in simple and clear everyday words. Explain what the feature does for the person and how they use it — the screens, buttons and steps they see — not how it is built. Leave out code, file names, functions, endpoints, database tables, config keys and other internal names. Give technical detail only when the question explicitly asks for it, and then still say in plain words what it means. If a technical term cannot be avoided, explain it in a few words.",
    "7. Be concise: answer the question, do not restate the documentation.",
    "8. Unless you used rule 3, end with one line `_Sources:_` listing what you used as `project › path › heading`, separated by `; `.",
    "9. You have no tools and nobody can answer a follow-up question from you; if the question is ambiguous, answer the most likely reading and say which one you chose.",
    "",
    "── DOCUMENTATION FRAGMENTS ──",
    docsBlock(input.docs),
    "",
    "── THREAD SO FAR ──",
    input.transcript.length ? input.transcript.map((l) => `${l.who}: ${l.text}`).join("\n") : "(none — this is the first message)",
    "",
    "── QUESTION ──",
    input.question,
  ].join("\n");
}

// ── Answering ────────────────────────────────────────────────────────────────────

// Posted the moment a question is accepted and edited into the answer: an LLM answer takes
// tens of seconds, and a silent channel reads as a bot that did not hear.
export const SLACK_PLACEHOLDER = "_Looking through the documentation…_";

// No index anywhere in the workspace: said without spending a model call, because a model
// handed zero fragments could only say «not built» — which would be a lie about the product.
export const SLACK_NOT_INDEXED =
  "The documentation of this Kermanych workspace is not indexed yet, so there is nothing I can answer from. Index it from a project's Documentation tab in Kermanych.";

// Per project, the same match count the management chat's documentation turns retrieve.
export const SLACK_MATCH_COUNT = 8;

// How much of a long thread the model reads: the root question plus the newest replies
// before the follow-up. The discussion right before a mention is what it is about; the
// middle of a hundred-message thread is not worth the prompt.
const THREAD_CONTEXT = 60;

// The three Slack Web API calls an answer makes, signed with the bot token.
export type SlackThreadPort = {
  replies(channel: string, ts: string): Promise<SlackRawMessage[]>;
  postMessage(channel: string, threadTs: string | undefined, text: string): Promise<{ ts: string }>;
  update(channel: string, ts: string, text: string): Promise<void>;
};

// What a host supplies; everything else about an answer is decided here.
export type SlackAnswerHost = {
  slack: SlackThreadPort;
  botUserId: string;
  // Every project of the workspace that has a documentation index, with its matches for
  // `query` (best first). An empty list means nothing is indexed anywhere.
  searchDocs(query: string): Promise<SlackPromptDocs[]>;
  // Only flavours the prompt; a failure here must not cost the answer.
  workspaceName(): Promise<string | undefined>;
  generate(prompt: string): Promise<string>;
  // The short reason the apology shows, e.g. a coded runtime error's code.
  failureReason(err: unknown): string;
  warn(message: string): void;
};

// Turns the placeholder at `placeholderTs` into the answer to `ask`. Never throws: a
// failure becomes an apology in the thread and a warning in the host's log.
export async function answerSlackAsk(ask: SlackAsk, placeholderTs: string, host: SlackAnswerHost): Promise<void> {
  const { slack } = host;
  // Once the placeholder holds the start of the answer, a failure further on must not
  // overwrite it: the apology goes after it instead.
  let started = false;
  try {
    let transcript: TranscriptLine[] = [];
    let query = ask.text;
    if (ask.kind === "followup") {
      // Only what was said up to the follow-up: later replies were not part of the
      // question, and the placeholder is the answer being written.
      const before = (await slack.replies(ask.channel, ask.threadTs)).filter((m) => Number(m.ts) < Number(ask.ts));
      const kept = before.length > THREAD_CONTEXT ? [before[0]!, ...before.slice(-(THREAD_CONTEXT - 1))] : before;
      transcript = threadTranscript(kept, host.botUserId, placeholderTs);
      // Retrieval sees the root question too: «and on mobile?» alone matches nothing.
      if (transcript[0]) query = `${transcript[0].text}\n${ask.text}`;
    }

    const docs = await host.searchDocs(query);
    if (docs.length === 0) {
      await slack.update(ask.channel, placeholderTs, SLACK_NOT_INDEXED);
      return;
    }

    const workspaceName = await host.workspaceName().catch(() => undefined);
    const prompt = buildSlackAnswerPrompt({
      ...(workspaceName ? { workspaceName } : {}),
      transcript,
      question: ask.text,
      docs,
    });
    const text = await host.generate(prompt);
    // The placeholder becomes the first part; a longer answer continues in the thread,
    // one message per part, in order.
    const [first, ...rest] = splitForSlack(toSlackMrkdwn(text));
    await slack.update(ask.channel, placeholderTs, first!);
    started = true;
    for (const part of rest) await slack.postMessage(ask.channel, ask.threadTs, part);
  } catch (err) {
    const reason = host.failureReason(err);
    host.warn(`slack: answering in ${ask.channel} failed — ${reason}`);
    const apology = `_Sorry, I could not answer this one (${reason})._`;
    await (started
      ? slack.postMessage(ask.channel, ask.threadTs, apology)
      : slack.update(ask.channel, placeholderTs, apology)
    ).catch((e: Error) => host.warn(`slack: posting the apology failed — ${e.message}`));
  }
}

// ── Cloud answers: the owner's AI provider ───────────────────────────────────────
// The cloud host has no agent runtime, so it calls a model API directly with the key the
// workspace owner stored. «openai» is any OpenAI-compatible chat-completions API (OpenAI
// itself, or OpenRouter, Groq, Mistral, Gemini's OpenAI endpoint, a gateway) — the base URL
// picks which.

export const SLACK_CLOUD_AI_PROVIDERS = ["anthropic", "openai"] as const;
export type SlackCloudAiProvider = (typeof SLACK_CLOUD_AI_PROVIDERS)[number];

export function isSlackCloudAiProvider(v: unknown): v is SlackCloudAiProvider {
  return typeof v === "string" && (SLACK_CLOUD_AI_PROVIDERS as readonly string[]).includes(v);
}

// Anthropic's default is the desktop bot's own model (apps/api management-chat.service.ts
// DOCS_MODEL), so a cloud answer out of the box is the same model reading the same prompt.
export const SLACK_CLOUD_DEFAULT_MODELS: Record<SlackCloudAiProvider, string> = {
  anthropic: "claude-sonnet-5",
  openai: "gpt-5",
};

export const SLACK_CLOUD_OPENAI_BASE_URL = "https://api.openai.com/v1";

export type SlackCloudAi = {
  provider: SlackCloudAiProvider;
  model: string;
  apiKey: string;
  // «openai» only; unset = OpenAI itself.
  baseUrl?: string;
};

// Room for a long answer; splitForSlack carries it into as many messages as it needs.
const ANSWER_MAX_TOKENS = 8_000;

// A provider error as a short reason for the apology and the owner's toast. The key never
// appears in it — only the provider's own message.
async function providerError(provider: SlackCloudAiProvider, res: Response): Promise<Error> {
  const body = (await res.json().catch(() => null)) as { error?: { message?: string } | string } | null;
  const msg = typeof body?.error === "string" ? body.error : body?.error?.message;
  return new Error(`${provider} ${res.status}${msg ? `: ${msg}` : ""}`);
}

// One prompt, one answer, no tools — the cloud counterpart of the desktop's tool-less
// one-shot child. `maxTokens` only bounds Anthropic, which requires it; OpenAI-compatible
// APIs disagree on the parameter's name, so none is sent there.
export async function slackCloudGenerate(
  ai: SlackCloudAi,
  prompt: string,
  opts: { maxTokens?: number; signal?: AbortSignal } = {},
): Promise<string> {
  if (ai.provider === "anthropic") {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "content-type": "application/json", "x-api-key": ai.apiKey, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({
        model: ai.model,
        max_tokens: opts.maxTokens ?? ANSWER_MAX_TOKENS,
        messages: [{ role: "user", content: prompt }],
      }),
      ...(opts.signal ? { signal: opts.signal } : {}),
    });
    if (!res.ok) throw await providerError(ai.provider, res);
    const j = (await res.json()) as { content?: Array<{ type?: string; text?: string }> };
    const text = (j.content ?? [])
      .filter((b) => b.type === "text")
      .map((b) => b.text ?? "")
      .join("")
      .trim();
    if (!text) throw new Error("anthropic: empty answer");
    return text;
  }
  const base = (ai.baseUrl?.trim() || SLACK_CLOUD_OPENAI_BASE_URL).replace(/\/+$/, "");
  const res = await fetch(`${base}/chat/completions`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${ai.apiKey}` },
    body: JSON.stringify({ model: ai.model, messages: [{ role: "user", content: prompt }] }),
    ...(opts.signal ? { signal: opts.signal } : {}),
  });
  if (!res.ok) throw await providerError(ai.provider, res);
  const j = (await res.json()) as { choices?: Array<{ message?: { content?: string | null } }> };
  const text = (j.choices?.[0]?.message?.content ?? "").trim();
  if (!text) throw new Error("openai: empty answer");
  return text;
}
